#include <iostream>

template <typename T>
T max_of(T a, T b) {
    return a > b ? a : b;
}

int main() {
    int a = 0;
    int b = 0;
    double x = 0.0;
    double y = 0.0;
    std::cin >> a >> b;
    std::cin >> x >> y;
    std::cout << max_of(a, b) << std::endl;
    std::cout << max_of(x, y) << std::endl;
    return 0;
}
